import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#020617', card: '#0f172a', accent: '#38bdf8', 
  gold: '#fbbf24', text: '#f8fafc', muted: '#94a3b8', 
  border: '#1e293b', success: '#22c55e', danger: '#ef4444'
};

export default function App() {
  const [isLogged, setIsLogged] = useState(true); // Já entramos
  const [user, setUser] = useState({ name: 'Dr. Rodrigo', office: 'Rodrigo Advocacia' });
  const [tab, setTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_v9_data');
    // Dados iniciais para o gráfico não vir vazio
    return salvo ? JSON.parse(salvo) : [
      { id: 1, cliente: 'Empresa Alpha', valor: '15000', area: 'Tributário', data: '2026-05-01' },
      { id: 2, cliente: 'João Silva', valor: '5000', area: 'Cível', data: '2026-05-10' }
    ];
  });

  useEffect(() => {
    localStorage.setItem('juris_v9_data', JSON.stringify(processos));
  }, [processos]);

  // Cálculos de BI
  const total = processos.reduce((a, b) => a + Number(b.valor), 0);
  const areas = {
    Cível: processos.filter(p => p.area === 'Cível').length,
    Trabalhista: processos.filter(p => p.area === 'Trabalhista').length,
    Tributário: processos.filter(p => p.area === 'Tributário').length,
  };

  return (
    <div style={s.app}>
      <aside style={s.sidebar} className="no-print">
        <div style={s.brand}><div style={s.brandIcon}>J</div> JurisPRO</div>
        <nav style={s.nav}>
          <div style={s.navLink(tab === 'dashboard')} onClick={() => setTab('dashboard')}>📊 Dashboard BI</div>
          <div style={s.navLink(tab === 'processos')} onClick={() => setTab('processos')}>📂 Processos</div>
          <div style={s.navLink(tab === 'config')} onClick={() => setTab('config')}>⚙️ Configurações</div>
        </nav>
        <div style={s.userBadge}>
          <div style={s.avatar}>R</div>
          <div>
            <div style={{fontSize: '13px', fontWeight: 'bold'}}>{user.name}</div>
            <div style={{fontSize: '10px', color: COLORS.success}}>CONEXÃO SEGURA</div>
          </div>
        </div>
      </aside>

      <main style={s.content}>
        <header style={s.header}>
          <div>
            <h2 style={{margin: 0}}>{tab === 'dashboard' ? 'Business Intelligence' : 'Gestão'}</h2>
            <p style={{color: COLORS.muted, fontSize: '14px'}}>{user.office}</p>
          </div>
          <div style={s.dateBadge}>{new Date().toLocaleDateString()}</div>
        </header>

        {tab === 'dashboard' && (
          <div style={s.grid}>
            <StatCard label="Patrimônio Total" value={`R$ ${total.toLocaleString()}`} color={COLORS.success} />
            <StatCard label="Média por Processo" value={`R$ ${(total/(processos.length || 1)).toLocaleString()}`} color={COLORS.accent} />
            <StatCard label="Casos Ativos" value={processos.length} color={COLORS.gold} />

            {/* GRÁFICO DE DISTRIBUIÇÃO ANALÍTICO */}
            <div style={{...s.card, gridColumn: 'span 2'}}>
              <h4 style={{marginTop: 0}}>Distribuição de Demanda por Área</h4>
              <div style={{display: 'flex', gap: '30px', marginTop: '20px', alignItems: 'center'}}>
                {Object.keys(areas).map(area => (
                  <div key={area} style={{flex: 1}}>
                    <div style={{display: 'flex', justifyContent: 'space-between', fontSize: '12px', marginBottom: '8px'}}>
                      <span>{area}</span>
                      <span style={{fontWeight: 'bold'}}>{areas[area]} casos</span>
                    </div>
                    <div style={s.progressBg}>
                      <div style={s.progressFill((areas[area] / processos.length) * 100 || 0, area)} />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div style={s.card}>
              <h4 style={{marginTop: 0}}>Metas Mensais</h4>
              <div style={s.circularProgress}>
                <div style={s.innerCircle}>85%</div>
              </div>
              <p style={{fontSize: '11px', textAlign: 'center', color: COLORS.muted, marginTop: '10px'}}>Meta de honorários atingida</p>
            </div>
          </div>
        )}

        {tab === 'processos' && (
          <div style={s.card}>
            <h3>📂 Lista de Processos Ativos</h3>
            <table style={s.table}>
              <thead>
                <tr>
                  <th style={s.th}>CLIENTE</th>
                  <th style={s.th}>ÁREA</th>
                  <th style={s.th}>VALOR</th>
                </tr>
              </thead>
              <tbody>
                {processos.map(p => (
                  <tr key={p.id}>
                    <td style={s.td}><strong>{p.cliente}</strong></td>
                    <td style={s.td}>{p.area}</td>
                    <td style={s.td}>R$ {Number(p.valor).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}

const StatCard = ({label, value, color}) => (
  <div style={s.card}>
    <div style={{color: COLORS.muted, fontSize: '11px', fontWeight: 'bold'}}>{label.toUpperCase()}</div>
    <div style={{fontSize: '28px', fontWeight: 'bold', color: color, marginTop: '10px'}}>{value}</div>
